import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { Carousel, Row, Col, Card, Button } from 'react-bootstrap';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faStar, faStarHalfAlt, faBook } from '@fortawesome/free-solid-svg-icons';
import axios from 'axios';

const Home = () => {
  const [featuredManga, setFeaturedManga] = useState([]);
  const [newManga, setNewManga] = useState([]);
  const [categories, setCategories] = useState([]);
  const [popularAuthors, setPopularAuthors] = useState([]);

  useEffect(() => {
    // Fetch data from API
    const fetchData = async () => {
      try {
        const [featuredRes, newRes, categoriesRes, authorsRes] = await Promise.all([
          axios.get('/api/manga/featured'),
          axios.get('/api/manga/new'),
          axios.get('/api/categories'),
          axios.get('/api/authors/popular')
        ]);

        setFeaturedManga(featuredRes.data);
        setNewManga(newRes.data);
        setCategories(categoriesRes.data);
        setPopularAuthors(authorsRes.data);
      } catch (error) {
        console.error('Error fetching data:', error);
      }
    };

    fetchData();
  }, []);

  const renderRatingStars = (rating) => {
    const stars = [];
    const fullStars = Math.floor(rating);
    const hasHalfStar = rating % 1 !== 0;

    for (let i = 0; i < fullStars; i++) {
      stars.push(<FontAwesomeIcon key={i} icon={faStar} className="text-warning" />);
    }

    if (hasHalfStar) {
      stars.push(<FontAwesomeIcon key="half" icon={faStarHalfAlt} className="text-warning" />);
    }

    return stars;
  };

  const MangaCard = ({ manga }) => (
    <Card className="manga-card h-100">
      <Card.Img variant="top" src={manga.coverImage} alt={manga.title} />
      <Card.Body>
        <span className="category-badge mb-2">{manga.category}</span>
        <Card.Title>{manga.title}</Card.Title>
        <div className="rating mb-2">
          {renderRatingStars(manga.rating)}
          <span className="ms-1">{manga.rating}</span>
        </div>
        <p className="price mb-2">{manga.price.toLocaleString('vi-VN')} đ</p>
        <Button variant="primary" className="w-100">Thêm vào giỏ</Button>
      </Card.Body>
    </Card>
  );

  return (
    <>
      {/* Banner Section */}
      <Carousel className="mb-4">
        <Carousel.Item>
          <img
            className="d-block w-100"
            src="https://via.placeholder.com/1200x400"
            alt="First slide"
          />
          <Carousel.Caption>
            <h5>Khuyến mãi đặc biệt</h5>
            <p>Giảm giá lên đến 50% cho các bộ manga hot</p>
          </Carousel.Caption>
        </Carousel.Item>
        <Carousel.Item>
          <img
            className="d-block w-100"
            src="https://via.placeholder.com/1200x400"
            alt="Second slide"
          />
          <Carousel.Caption>
            <h5>Bộ sưu tập mới</h5>
            <p>Khám phá các tựa truyện mới nhất</p>
          </Carousel.Caption>
        </Carousel.Item>
        <Carousel.Item>
          <img
            className="d-block w-100"
            src="https://via.placeholder.com/1200x400"
            alt="Third slide"
          />
          <Carousel.Caption>
            <h5>Manga bán chạy</h5>
            <p>Top những bộ manga được yêu thích nhất</p>
          </Carousel.Caption>
        </Carousel.Item>
      </Carousel>

      {/* Featured Manga Section */}
      <section className="mb-5">
        <div className="d-flex justify-content-between align-items-center mb-4">
          <h2>Truyện nổi bật</h2>
          <Link to="/featured" className="btn btn-outline-primary">Xem tất cả</Link>
        </div>
        <Row xs={1} md={2} lg={4} className="g-4">
          {featuredManga.map(manga => (
            <Col key={manga.id}>
              <MangaCard manga={manga} />
            </Col>
          ))}
        </Row>
      </section>

      {/* New Releases Section */}
      <section className="mb-5">
        <div className="d-flex justify-content-between align-items-center mb-4">
          <h2>Truyện mới</h2>
          <Link to="/new-releases" className="btn btn-outline-primary">Xem tất cả</Link>
        </div>
        <Row xs={1} md={2} lg={4} className="g-4">
          {newManga.map(manga => (
            <Col key={manga.id}>
              <MangaCard manga={manga} />
            </Col>
          ))}
        </Row>
      </section>

      {/* Categories Section */}
      <section className="mb-5">
        <h2 className="mb-4">Thể loại manga</h2>
        <Row xs={2} md={3} lg={6} className="g-3">
          {categories.map(category => (
            <Col key={category.id}>
              <Link to={`/category/${category.id}`} className="text-decoration-none">
                <Card className="h-100 text-center">
                  <Card.Body>
                    <FontAwesomeIcon icon={faBook} size="2x" className="mb-2" />
                    <Card.Title>{category.name}</Card.Title>
                    <Card.Text className="text-muted">{category.count} truyện</Card.Text>
                  </Card.Body>
                </Card>
              </Link>
            </Col>
          ))}
        </Row>
      </section>

      {/* Popular Authors Section */}
      <section className="mb-5">
        <h2 className="mb-4">Tác giả nổi tiếng</h2>
        <Row xs={2} md={3} lg={6} className="g-4">
          {popularAuthors.map(author => (
            <Col key={author.id}>
              <Card className="h-100 text-center">
                <Card.Img
                  variant="top"
                  src={author.image}
                  className="rounded-circle p-3"
                  alt={author.name}
                />
                <Card.Body>
                  <Card.Title>{author.name}</Card.Title>
                  <Card.Text className="text-muted">{author.mangaCount} tác phẩm</Card.Text>
                </Card.Body>
              </Card>
            </Col>
          ))}
        </Row>
      </section>
    </>
  );
};

export default Home;
